use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < 'graph , G > TriColorDepthFirstSearch < 'graph , G > where G : ? Sized + DirectedGraph + Successors , { pub fn new (graph : & 'graph G) -> Self { TriColorDepthFirstSearch { graph , stack : vec ! [] , visited : DenseBitSet :: new_empty (graph . num_nodes ()) , settled : DenseBitSet :: new_empty (graph . num_nodes ()) , } } # [doc = " Performs a depth-first search, starting from the given `root`."] # [doc = ""] # [doc = " This won't visit nodes that are not reachable from `root`."] pub fn run_from < V > (mut self , root : G :: Node , visitor : & mut V) -> Option < V :: BreakVal > where V : TriColorVisitor < G > , { use NodeStatus :: { Settled , Visited } ; self . stack . push (Event { node : root , becomes : Visited }) ; loop { match self . stack . pop () ? { Event { node , becomes : Settled } => { let not_previously_settled = self . settled . insert (node) ; assert ! (not_previously_settled , "A node should be settled exactly once") ; if let ControlFlow :: Break (val) = visitor . node_settled (node) { return Some (val) ; } } Event { node , becomes : Visited } => { let not_previously_visited = self . visited . insert (node) ; let prior_status = if not_previously_visited { None } else if self . settled . contains (node) { Some (Settled) } else { Some (Visited) } ; if let ControlFlow :: Break (val) = visitor . node_examined (node , prior_status) { return Some (val) ; } if prior_status . is_some () { continue ; } self . stack . push (Event { node , becomes : Settled }) ; for succ in self . graph . successors (node) { if ! visitor . ignore_edge (node , succ) { self . stack . push (Event { node : succ , becomes : Visited }) ; } } } } } } }